style.css:
/* Roblox Safe Cute Pink Theme */

html, body {
    background-color: #ffe4ec !important; /* very light pink background */
    color: #4a2c3a !important;
    font-family: "Poppins", "Comic Neue", "Quicksand", cursive, sans-serif !important;
}

/* Pink overlay to fill sides */
html::before, body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: #ffe4ec !important;
    z-index: -1;
}

/* Text and links */
body, h1, h2, h3, p, span, a, input, textarea {
    color: #4a2c3a !important;
    font-family: inherit !important;
}

a {
    color: #ff9ac2 !important;
    text-decoration: none !important;
}

a:hover {
    text-decoration: underline !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-thumb {
    background: #ff9ac2 !important;
    border-radius: 10px;
}
